# Songbird logo for the idle screen: 128x64, 1-bit, MONO_HLSB.
# Regenerate from a source image with the packer in the project notes.
import binascii
import framebuf

_LOGO = binascii.unhexlify(
    ""
)
_fb = framebuf.FrameBuffer(bytearray(_LOGO), 128, 64, framebuf.MONO_HLSB)


def draw_logo(d, status=""):
    d.fill(0)
    d.blit(_fb, 0, 0)
    if status:
        # readable status strip along the bottom, over the logo
        d.fill_rect(0, 55, 128, 9, 0)
        d.text(status[:21], 2, 56, 1)
    d.show()
